window.CODE_INDEX = {"classes":{"AppHeader":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"],["events","h-widgets","Screen \u00b7 widget composition"],["home-menu","h-widgets","Screen \u00b7 widget composition"],["home","h-widgets","Screen \u00b7 widget composition"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class AppHeader extends StatelessWidget {\n  const AppHeader({\n    super.key,\n    this.title,\n    this.subtitle,\n    this.showBackBtn = true,\n    this.isTransparent = false,\n    this.onBack,\n    this.trailing,\n    this.backIcon = AppIcons.prev,\n    this.backBtnSemantics,\n  });\n  final String? title;\n  final String? subtitle;\n  final bool showBackBtn;\n  final AppIcons backIcon;\n  final String? backBtnSemantics;\n  final bool isTransparent;\n  final VoidCallback? onBack;\n  final Widget Function(BuildContext context)? trailing;\n\n  @override\n  Widget build(BuildContext context) {\n    return ColoredBox(\n      color: isTransparent ? Colors.transparent : $styles.colors.black,\n      child: SafeArea(\n        bottom: false,\n        child: SizedBox(\n          height: 64 * $styles.scale,\n          child: Stack(\n            children: [\n              MergeSemantics(\n                child: Semantics(\n                  header: true,\n                  child: Center(\n                    child: Column(\n                      mainAxisSize: MainAxisSize.min,\n                      children: [\n                        if (title != null)\n                          Text(\n                            title!.toUpperCase(),\n                            textHeightBehavior: TextHeightBehavior(applyHeightToFirstAscent: false),\n                            style: $styles.text.h4.copyWith(\n                              color: $styles.colors.offWhite,\n                              fontWeight: FontWeight.w500,\n                            ),\n                          ),\n                        if (subtitle != null)\n                          Text(\n                            subtitle!.toUpperCase(),\n                            textHeightBehavior: TextHeightBehavior(applyHeightToFirstAscent: false),\n                            style: $styles.text.title1.copyWith(color: $styles.colors.accent1),\n                          ),\n                      ],\n                    ),\n                  ),\n                ),\n              ),\n              Positioned.fill(\n                child: Center(\n                  child: Row(\n                    children: [\n                      Gap($styles.insets.sm),\n                      if (showBackBtn)\n                        BackBtn(\n                          onPressed: onBack,\n                          icon: backIcon,\n                          semanticLabel: backBtnSemantics,\n                        ),\n                      Spacer(),\n                      if (trailing != null) trailing!.call(context),\n                      Gap($styles.insets.sm),\n                      //if (showBackBtn) Container(width: $styles.insets.lg * 2, alignment: Alignment.centerLeft, child: child),\n                    ],\n                  ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/common/controls/app_header.dart","kind":"class","line":4,"members":{"AppHeader":[5,15],"backBtnSemantics":[20,20],"backIcon":[19,19],"build":[25,86],"isTransparent":[21,21],"onBack":[22,22],"showBackBtn":[18,18],"subtitle":[17,17],"title":[16,16],"trailing":[23,23]},"shot":"shots/code/AppHeader.jpg","supers":["StatelessWidget"]},"AppLogic":{"appearsIn":[["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"],["editorial","h-classes","Logic \u00b7 class diagram"],["home-menu","h-sequence","Jump to a wonder, or switch language \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens talk through"],["photo-gallery","h-classes","Logic \u00b7 class diagram"],["photo-gallery","h-sequence","Swipe across the wall and open a photo \u00b7 sequence"],["splash","h-classes","Logic \u00b7 class diagram"],["splash","h-sequence","Launch the app \u00b7 sequence"],["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class AppLogic {\n  Size _appSize = Size.zero;\n\n  /// Indicates to the rest of the app that bootstrap has not completed.\n  /// The router will use this to prevent redirects while bootstrapping.\n  bool isBootstrapComplete = false;\n\n  /// Indicates which orientations the app will allow be default. Affects Android/iOS devices only.\n  /// Defaults to both landscape (hz) and portrait (vt)\n  List<Axis> supportedOrientations = [Axis.vertical, Axis.horizontal];\n\n  /// Allow a view to override the currently supported orientations. For example, [FullscreenVideoViewer] always wants to enable both landscape and portrait.\n  /// If a view sets this override, they are responsible for setting it back to null when finished.\n  List<Axis>? _supportedOrientationsOverride;\n  set supportedOrientationsOverride(List<Axis>? value) {\n    if (_supportedOrientationsOverride != value) {\n      _supportedOrientationsOverride = value;\n      _updateSystemOrientation();\n    }\n  }\n\n  /// Initialize the app and all main actors.\n  /// Loads settings, sets up services etc.\n  Future<void> bootstrap() async {\n    debugPrint('bootstrap start...');\n    // Set min-sizes for desktop apps\n    // TODO: Test on Linux and confirm whether it's safe to call there, according to issue #183 its not.\n    if (!kIsWeb && (PlatformInfo.isWindows || PlatformInfo.isMacOS)) {\n      await DesktopWindow.setMinWindowSize($styles.sizes.minAppSize);\n    }\n\n    if (kIsWeb) {\n      // SB: This is intentionally not a debugPrint, as it's a message for users who open the console on web.\n      // Display if running in WASM mode.\n      const isCompiledWithWasm = bool.fromEnvironment('dart.tool.dart2wasm');\n      final isRunningWithWasm = isCompiledWithWasm || isWasmOptInFromBootstrap;\n      PackageInfo packageInfo = await PackageInfo.fromPlatform();\n      print(\n        '''Thanks for checking out Wonderous on the web!\n        If you encounter any issues please report them at https://github.com/gskinnerTeam/flutter-wonderous-app/issues.\n        Version: ${packageInfo.version}  -  WASM-enabled: $isRunningWithWasm''',\n      );\n      // Required on web to automatically enable accessibility features\n      WidgetsFlutterBinding.ensureInitialized().ensureSemantics();\n    }\n\n    // Load any bitmaps the views might need\n    await AppBitmaps.init();\n\n    // Set preferred refresh rate to the max possible (the OS may ignore this)\n    if (!kIsWeb && PlatformInfo.isAndroid) {\n      await FlutterDisplayMode.setHighRefreshRate();\n    }\n\n    // Settings\n    await settingsLogic.load();\n\n    // Localizations\n    await localeLogic.load();\n\n    // Wonders Data\n    wondersLogic.init();\n\n    // Events\n    timelineLogic.init();\n\n    // Collectibles\n    collectiblesLogic.init();\n    await collectiblesLogic.load();\n\n    // Wait at least 1 frame to give GoRouter time to catch the initial deeplink\n    await Future.delayed(1.milliseconds);\n\n    // Flag bootStrap as complete\n    isBootstrapComplete = true;\n\n    // Load initial view (replace empty initial view which is covered by a native splash screen)\n    bool showIntro = settingsLogic.hasCompletedOnboarding.value == false;\n\n    // Use Router.neglect so /splash is replaced in browser history, preventing /splash from appearing as a back-navigation target.\n    final navigatorContext = appRouter.routerDelegate.navigatorKey.currentContext;\n    void doNavigate() {\n      if (showIntro) {\n        debugPrint('Shifting to intro screen');\n        appRouter.go(ScreenPaths.intro);\n      } else {\n        debugPrint('Shifting to initialDeeplink: $initialDeeplink (or home)');\n        appRouter.go(initialDeeplink ?? ScreenPaths.home);\n      }\n    }\n\n    if (navigatorContext != null) {\n      Router.neglect(navigatorContext, doNavigate);\n    } else {\n      doNavigate();\n    }\n  }\n\n  Future<T?> showFullscreenDialogRoute<T>(\n    BuildContext context,\n    Widget child, {\n    bool transparent = false,\n  }) async {\n    return await Navigator.of(context).push<T>(\n      PageRoutes.dialog<T>(child, duration: $styles.times.pageTransition),\n    );\n  }\n\n  /// Called from the UI layer once a MediaQuery has been obtained\n  void handleAppSizeChanged(Size appSize) {\n    /// Disable landscape layout on smaller form factors\n    bool isSmall = display.size.shortestSide / display.devicePixelRatio < 600;\n    supportedOrientations = isSmall ? [Axis.vertical] : [Axis.vertical, Axis.horizontal];\n    _updateSystemOrientation();\n    _appSize = appSize;\n  }\n\n  Display get display => PlatformDispatcher.instance.displays.first;\n\n  bool shouldUseNavRail() => _appSize.width > _appSize.height && _appSize.height > 250;\n\n  void _updateSystemOrientation() {\n    final axisList = _supportedOrientationsOverride ?? supportedOrientations;\n    //debugPrint('updateDeviceOrientation, supportedAxis: $axisList');\n    final orientations = <DeviceOrientation>[];\n    if (axisList.contains(Axis.vertical)) {\n      orientations.addAll([\n        DeviceOrientation.portraitUp,\n        DeviceOrientation.portraitDown,\n      ]);\n    }\n    if (axisList.contains(Axis.horizontal)) {\n      orientations.addAll([\n        DeviceOrientation.landscapeLeft,\n        DeviceOrientation.landscapeRight,\n      ]);\n    }\n    SystemChrome.setPreferredOrientations(orientations);\n  }\n\n  void precacheUrl(String url, BuildContext context) async {\n    await precacheImage(\n      AssetImage(url),\n      context,\n      onError: (error, stackTrace) {\n        print('Loading $url failed - ${error.toString()}');\n      },\n    );\n  }\n\n  void precacheIcons(BuildContext context) {\n    // Precache the active and idle icons for the navigation bar.\n    List<String> urls = [];\n    for (var i = 0; i < 2; i++) {\n      urls.add('${ImagePaths.common}/tab-editorial${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-photos${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-artifacts${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-timeline${i == 0 ? '-active' : ''}.png');\n    }\n    for (var url in urls) {\n      precacheUrl(url, context);\n    }\n  }\n\n  void precacheWonderImages(BuildContext context) {\n    List<String> urls = [\n      '${ImagePaths.root}/chichen_itza/chichen.png',\n      '${ImagePaths.root}/chichen_itza/foreground-left.png',\n      '${ImagePaths.root}/chichen_itza/foreground-right.png',\n      '${ImagePaths.root}/chichen_itza/top-left.png',\n      '${ImagePaths.root}/chichen_itza/top-right.png',\n      '${ImagePaths.root}/chichen_itza/sun.png',\n      '${ImagePaths.root}/christ_the_redeemer/redeemer.png',\n      '${ImagePaths.root}/christ_the_redeemer/foreground-left.png',\n      '${ImagePaths.root}/christ_the_redeemer/foreground-right.png',\n      '${ImagePaths.root}/christ_the_redeemer/sun.png',\n      '${ImagePaths.root}/colosseum/colosseum.png',\n      '${ImagePaths.root}/colosseum/foreground-left.png',\n      '${ImagePaths.root}/colosseum/foreground-right.png',\n      '${ImagePaths.root}/colosseum/sun.png',\n      '${ImagePaths.root}/great_wall_of_china/great-wall.png',\n      '${ImagePaths.root}/great_wall_of_china/foreground-left.png',\n      '${ImagePaths.root}/great_wall_of_china/foreground-right.png',\n      '${ImagePaths.root}/great_wall_of_china/sun.png',\n      '${ImagePaths.root}/machu_picchu/machu-picchu.png',\n      '${ImagePaths.root}/machu_picchu/foreground-back.png',\n      '${ImagePaths.root}/machu_picchu/foreground-front.png',\n      '${ImagePaths.root}/machu_picchu/sun.png',\n      '${ImagePaths.root}/petra/petra.png',\n      '${ImagePaths.root}/petra/foreground-left.png',\n      '${ImagePaths.root}/petra/foreground-right.png',\n      '${ImagePaths.root}/petra/moon.png',\n      '${ImagePaths.root}/pyramids/pyramids.png',\n      '${ImagePaths.root}/pyramids/foreground-back.png',\n      '${ImagePaths.root}/pyramids/foreground-front.png',\n      '${ImagePaths.root}/pyramids/moon.png',\n      '${ImagePaths.root}/taj_mahal/taj-mahal.png',\n      '${ImagePaths.root}/taj_mahal/foreground-left.png',\n      '${ImagePaths.root}/taj_mahal/foreground-right.png',\n      '${ImagePaths.root}/taj_mahal/sun.png',\n      '${ImagePaths.root}/taj_mahal/pool.png',\n    ];\n    List<String> folderNames = [\n      'chichen_itza',\n      'christ_the_redeemer',\n      'colosseum',\n      'great_wall_of_china',\n      'machu_picchu',\n      'petra',\n      'pyramids',\n      'taj_mahal',\n    ];\n\n    // Universals.\n    for (var name in folderNames) {\n      urls.add('${ImagePaths.root}/$name/flattened.jpg');\n      urls.add('${ImagePaths.root}/$name/wonder-button.png');\n      urls.add('${ImagePaths.root}/$name/photo-1.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-2.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-3.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-4.jpg');\n    }\n\n    for (var url in urls) {\n      precacheUrl(url, context);\n    }\n  }\n}","file":"lib/logic/app_logic.dart","kind":"class","line":14,"members":{"_appSize":[15,15],"_supportedOrientationsOverride":[25,27],"_updateSystemOrientation":[135,152],"bootstrap":[35,110],"display":[131,131],"handleAppSizeChanged":[122,129],"isBootstrapComplete":[17,19],"precacheIcons":[164,176],"precacheUrl":[154,162],"precacheWonderImages":[178,240],"shouldUseNavRail":[133,133],"showFullscreenDialogRoute":[112,120],"supportedOrientations":[21,23],"supportedOrientationsOverride":[28,33]},"supers":[]},"ArtifactAPILogic":{"appearsIn":[["artifacts","h-classes","Logic \u00b7 class diagram"],["artifacts","h-sequence","Search for an artifact and open it \u00b7 sequence"],["collection","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens talk through"]],"code":"class ArtifactAPILogic {\n  final HashMap<String, ArtifactData?> _artifactCache = HashMap();\n\n  ArtifactAPIService get service => GetIt.I.get<ArtifactAPIService>();\n\n  /// Returns artifact data by ID. Returns null if artifact cannot be found. */\n  Future<ArtifactData?> getArtifactByID(String id, {bool selfHosted = false}) async {\n    if (_artifactCache.containsKey(id)) return _artifactCache[id];\n    ServiceResult<ArtifactData?> result = (await (selfHosted\n        ? service.getSelfHostedObjectByID(id)\n        : service.getMetObjectByID(id)));\n    if (!result.success) throw $strings.artifactDetailsErrorNotFound(id);\n    ArtifactData? artifact = result.content;\n    return _artifactCache[id] = artifact;\n  }\n}","file":"lib/logic/artifact_api_logic.dart","kind":"class","line":8,"members":{"_artifactCache":[9,9],"getArtifactByID":[13,22],"service":[11,11]},"supers":[]},"CollectibleData":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"class CollectibleData {\n  CollectibleData({\n    required this.title,\n    required this.iconName,\n    required this.artifactId,\n    required this.wonder,\n  }) {\n    icon = AssetImage('${ImagePaths.collectibles}/$iconName.png');\n  }\n\n  final String title;\n  final String iconName;\n\n  late final ImageProvider icon;\n\n  final String artifactId;\n  final WonderType wonder;\n\n  String get id => artifactId;\n  String get subtitle => wondersLogic.getData(wonder).artifactCulture;\n\n  String get imageUrl => ArtifactData.getSelfHostedImageUrl(id);\n  String get imageUrlSmall => ArtifactData.getSelfHostedImageUrlSmall(id);\n}","file":"lib/logic/data/collectible_data.dart","kind":"class","line":10,"members":{"CollectibleData":[11,18],"artifactId":[25,25],"icon":[23,23],"iconName":[21,21],"id":[28,28],"imageUrl":[31,31],"imageUrlSmall":[32,32],"subtitle":[29,29],"title":[20,20],"wonder":[26,26]},"supers":[]},"CollectibleFoundScreen":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-widgets","Screen \u00b7 widget composition"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class CollectibleFoundScreen extends StatelessWidget {\n  // CollectibleItem passes in a (theoretically) pre-loaded imageProvider.\n  // we could check for load completion, and hold after introT, but that shouldn't be necessary in a real-world scenario.\n  const CollectibleFoundScreen({required this.collectible, required this.imageProvider, super.key});\n\n  final CollectibleData collectible;\n  final ImageProvider imageProvider;\n\n  @override\n  Widget build(BuildContext context) {\n    return RepaintBoundary(\n      child: _buildIntro(context).animate().swap(\n        delay: 1050.animateMs,\n        builder: (_, _) => _buildDetail(context),\n      ),\n    );\n  }\n\n  Widget _buildIntro(BuildContext context) {\n    Duration t = $styles.times.fast;\n    return Stack(\n      children: [\n        Animate().custom(\n          duration: t * 5,\n          builder: (context, ratio, _) => _buildGradient(context, ratio, 0),\n        ),\n\n        // icon is handled by Hero initially, then scales slowly:\n        Center(\n          child:\n              FractionallySizedBox(\n                    widthFactor: 0.33,\n                    heightFactor: 0.33,\n                    child: Hero(\n                      tag: 'collectible_icon_${collectible.id}',\n                      child: Image(\n                        image: collectible.icon,\n                        fit: BoxFit.contain,\n                      ),\n                    ),\n                  )\n                  .animate()\n                  .scale(\n                    begin: Offset(1.5, 1.5),\n                    end: Offset(3, 3),\n                    curve: Curves.easeInExpo,\n                    delay: t,\n                    duration: t * 3,\n                  )\n                  .fadeOut(),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildDetail(BuildContext context) {\n    Duration t = $styles.times.fast;\n    bool smallMode = context.heightPx < 550;\n    return Stack(\n      key: ValueKey('detail'),\n      children: [\n        /// Background\n        AppBackdrop(\n          strength: .5,\n          child: Container(color: $styles.colors.greyStrong.withValues(alpha: .96)),\n        ).animate().fadeIn(),\n\n        /// Particles\n        _CelebrationParticles(fadeMs: (t * 6).inMilliseconds),\n\n        /// invisible close btn\n        PopNavigatorUnderlay(),\n\n        /// Content\n        SafeArea(\n          child: CenteredBox(\n            width: $styles.sizes.maxContentWidth3,\n            child: Column(\n              children: [\n                Gap(smallMode ? $styles.insets.sm : $styles.insets.lg),\n                Spacer(),\n                SizedBox(\n                  height: context.heightPx * .35,\n                  child: Center(\n                    child: Hero(\n                      tag: 'collectible_image_${collectible.id}',\n                      child: _buildImage(context),\n                    ),\n                  ),\n                ),\n                Gap(smallMode ? $styles.insets.sm : $styles.insets.lg),\n                _buildRibbon(context),\n                Gap($styles.insets.sm),\n                _buildTitle(\n                  context,\n                  collectible.title,\n                  smallMode ? $styles.text.h2.copyWith(fontSize: 26) : $styles.text.h2,\n                  $styles.colors.offWhite,\n                  t * 1.5,\n                ),\n                Gap($styles.insets.xs),\n                _buildTitle(\n                  context,\n                  collectible.subtitle.toUpperCase(),\n                  $styles.text.title2,\n                  $styles.colors.accent1,\n                  t * 2,\n                ),\n                Spacer(),\n                Gap(smallMode ? $styles.insets.sm : $styles.insets.lg),\n                _buildCollectionButton(context),\n                Gap(smallMode ? $styles.insets.sm : $styles.insets.lg),\n                Spacer(),\n              ],\n            ),\n          ),\n        ),\n        AppHeader(isTransparent: true).animate().fade(delay: t * 4, duration: t * 2),\n      ],\n    );\n  }\n\n  Widget _buildGradient(BuildContext context, double ratioIn, double ratioOut) {\n    // used by both intro and detail animations to ensure they share a mid-point.\n    ratioIn = Curves.easeOutExpo.transform(ratioIn);\n    final double opacity = 1.0 * (ratioIn * 0.8 + ratioOut * 0.2);\n    final Color light = $styles.colors.offWhite;\n    final Color dark = $styles.colors.black;\n\n    // final state is a solid fill, so optimize that case:\n    if (ratioOut == 1) return Container(color: dark.withValues(alpha: opacity));\n\n    return Container(\n      decoration: BoxDecoration(\n        gradient: RadialGradient(\n          colors: [\n            Color.lerp(light, dark, ratioOut)!.withValues(alpha: opacity),\n            dark.withValues(alpha: opacity),\n          ],\n          stops: [0.2, min(1, 0.25 + ratioIn * 0.5 + ratioOut * 0.5)],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildImage(BuildContext context) {\n    Duration t = $styles.times.fast;\n    // build an image with animated shadows and scaling\n    return AppImage(image: imageProvider, scale: 1.0)\n        .animate()\n        .custom(\n          duration: t * 6,\n          builder: (_, ratio, child) => Container(\n            padding: EdgeInsets.all($styles.insets.xxs),\n            margin: EdgeInsets.symmetric(horizontal: $styles.insets.xl),\n            decoration: BoxDecoration(\n              color: $styles.colors.offWhite,\n              boxShadow: [\n                BoxShadow(\n                  color: $styles.colors.accent1.withValues(alpha: ratio * 0.75),\n                  blurRadius: $styles.insets.xl * 2,\n                ),\n                BoxShadow(\n                  color: $styles.colors.black.withValues(alpha: ratio * 0.75),\n                  offset: Offset(0, $styles.insets.xxs),\n                  blurRadius: $styles.insets.sm,\n                ),\n              ],\n            ),\n            child: child,\n          ),\n        )\n        .scale(\n          begin: Offset(0.3, 0.3),\n          duration: t * 2,\n          curve: Curves.easeOutExpo,\n          alignment: Alignment(0, 0.7),\n        );\n  }\n\n  Widget _buildRibbon(BuildContext context) {\n    Duration t = $styles.times.fast;\n    return _AnimatedRibbon(\n      $strings.collectibleFoundTitleArtifactDiscovered.toUpperCase(),\n    ).animate().scale(\n      begin: Offset(0.3, 0.3),\n      duration: t * 2,\n      curve: Curves.easeOutExpo,\n      alignment: Alignment(0, -1),\n    );\n  }\n\n  Widget _buildTitle(\n    BuildContext context,\n    String text,\n    TextStyle style,\n    Color color,\n    Duration delay,\n  ) {\n    Duration t = $styles.times.fast;\n    // because this is a performance-sensitive screen, we are fading in the text by adjusting color:\n    return Container(\n      padding: EdgeInsets.symmetric(horizontal: $styles.insets.lg),\n      child: Animate().custom(\n        delay: delay,\n        duration: t * 2,\n        builder: (_, m, _) => Text(\n          text,\n          maxLines: 2,\n          overflow: TextOverflow.ellipsis,\n          textAlign: TextAlign.center,\n          style: style.copyWith(color: color.withValues(alpha: m)),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildCollectionButton(BuildContext context) {\n    Duration t = $styles.times.med;\n    return AppBtn.from(\n          text: $strings.collectibleFoundButtonViewCollection,\n          isSecondary: true,\n          onPressed: () => _handleViewCollectionPressed(context),\n        )\n        .animate()\n        .fadeIn(delay: t)\n        .move(\n          begin: Offset(0, 50),\n          duration: t,\n          curve: Curves.easeOutCubic,\n        );\n  }\n\n  void _handleViewCollectionPressed(BuildContext context) {\n    Navigator.pop(context);\n    context.go(ScreenPaths.collection(collectible.id));\n  }\n}","file":"lib/ui/screens/collectible_found/collectible_found_screen.dart","kind":"class","line":14,"members":{"CollectibleFoundScreen":[17,17],"_buildCollectionButton":[231,245],"_buildDetail":[69,134],"_buildGradient":[136,157],"_buildImage":[159,192],"_buildIntro":[32,67],"_buildRibbon":[194,204],"_buildTitle":[206,229],"_handleViewCollectionPressed":[247,250],"build":[22,30],"collectible":[19,19],"imageProvider":[20,20]},"supers":["StatelessWidget"]},"CollectibleItem":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"]],"code":"class CollectibleItem extends StatelessWidget with GetItMixin {\n  CollectibleItem(this.collectible, {this.size = 64.0, super.key, this.focus}) {\n    // pre-fetch the image, so it's ready if we show the collectible found screen.\n    _imageProvider = NetworkImage(collectible.imageUrl);\n    _imageProvider.resolve(ImageConfiguration()).addListener(ImageStreamListener((_, _) {}));\n  }\n\n  final CollectibleData collectible;\n  final double size;\n  late final ImageProvider _imageProvider;\n  final FocusNode? focus;\n\n  void _handleTap(BuildContext context) async {\n    final screen = CollectibleFoundScreen(collectible: collectible, imageProvider: _imageProvider);\n    appLogic.showFullscreenDialogRoute(context, screen, transparent: true);\n    AppHaptics.mediumImpact();\n\n    // wait to update the state, to ensure the hero works properly:\n    await Future.delayed($styles.times.pageTransition);\n    collectiblesLogic.setState(collectible.id, CollectibleState.discovered);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final states = watchX((CollectiblesLogic c) => c.statesById);\n    bool isLost = states[collectible.id] == CollectibleState.lost;\n    // Use an OpeningCard to let the collectible smoothly collapse its size once it has been found\n    return SizedBox(\n      height: isLost ? size : null,\n      child: RepaintBoundary(\n        child: OpeningCard(\n          isOpen: isLost,\n          // Note: In order for the collapse animation to run properly, we must return a non-zero height or width.\n          closedBuilder: (_) => SizedBox(width: 1, height: 0),\n          openBuilder: (_) => AppBtn.basic(\n            focusNode: focus,\n            semanticLabel: $strings.collectibleItemSemanticCollectible,\n            onPressed: () => _handleTap(context),\n            enableFeedback: false,\n            child:\n                Hero(\n                      tag: 'collectible_icon_${collectible.id}',\n                      child: Image(\n                        image: collectible.icon,\n                        width: size,\n                        height: size,\n                        fit: BoxFit.contain,\n                      ),\n                    )\n                    .maybeAnimate(onPlay: (controller) => controller.repeat())\n                    .shimmer(delay: 4000.delayMs, duration: $styles.times.med * 3)\n                    .shake(curve: Curves.easeInOutCubic, hz: 4)\n                    .scale(\n                      begin: Offset(1.0, 1.0),\n                      end: Offset(1.1, 1.1),\n                      duration: $styles.times.med,\n                    )\n                    .then(delay: $styles.times.med)\n                    .scale(begin: Offset(1.0, 1.0), end: Offset(1 / 1.1, 1 / 1.1)),\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/common/collectible_item.dart","kind":"class","line":10,"members":{"CollectibleItem":[11,15],"_handleTap":[22,30],"_imageProvider":[19,19],"build":[32,73],"collectible":[17,17],"focus":[20,20],"size":[18,18]},"shot":"shots/code/CollectibleItem.jpg","supers":["StatelessWidget","GetItMixin"]},"CollectibleState":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"]],"code":"class CollectibleState {\n  static const int lost = 0;\n  static const int discovered = 1;\n  static const int explored = 2;\n}","file":"lib/logic/data/collectible_data.dart","kind":"class","line":4,"members":{"discovered":[6,6],"explored":[7,7],"lost":[5,5]},"supers":[]},"CollectiblesLogic":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens talk through"],["photo-gallery","h-classes","Logic \u00b7 class diagram"],["splash","h-classes","Logic \u00b7 class diagram"],["splash","h-sequence","Launch the app \u00b7 sequence"]],"code":"class CollectiblesLogic with ThrottledSaveLoadMixin {\n  @override\n  String get fileName => 'collectibles.dat';\n\n  /// Holds all collectibles that the views should care about\n  final List<CollectibleData> all = collectiblesData;\n\n  /// Current state for each collectible\n  late final statesById = ValueNotifier<Map<String, int>>({})..addListener(_updateCounts);\n\n  int _discoveredCount = 0;\n\n  int get discoveredCount => _discoveredCount;\n\n  int _exploredCount = 0;\n\n  int get exploredCount => _exploredCount;\n\n  late final _nativeWidget = GetIt.I<NativeWidgetService>();\n\n  void init() => _nativeWidget.init();\n\n  CollectibleData? fromId(String? id) => id == null ? null : all.firstWhereOrNull((o) => o.id == id);\n\n  List<CollectibleData> forWonder(WonderType wonder) {\n    return all.where((o) => o.wonder == wonder).toList(growable: false);\n  }\n\n  void setState(String id, int state) {\n    Map<String, int> states = Map.of(statesById.value);\n    states[id] = state;\n    statesById.value = states;\n    if (state == CollectibleState.discovered) {\n      final data = fromId(id)!;\n      _updateNativeHomeWidgetData(\n        title: data.title,\n        id: data.id,\n        imageUrl: data.imageUrlSmall,\n      );\n    }\n    scheduleSave();\n  }\n\n  void _updateCounts() {\n    _discoveredCount = _exploredCount = 0;\n    statesById.value.forEach((_, state) {\n      if (state == CollectibleState.discovered) _discoveredCount++;\n      if (state == CollectibleState.explored) _exploredCount++;\n    });\n    final foundCount = discoveredCount + exploredCount;\n    _nativeWidget.save<int>('discoveredCount', foundCount).then((value) {\n      _nativeWidget.markDirty();\n    });\n\n    debugPrint('setting discoveredCount for home widget $foundCount');\n  }\n\n  /// Get a discovered item, sorted by the order of wondersLogic.all\n  CollectibleData? getFirstDiscoveredOrNull() {\n    List<CollectibleData> discovered = [];\n    statesById.value.forEach((key, value) {\n      if (value == CollectibleState.discovered) discovered.add(fromId(key)!);\n    });\n    for (var w in wondersLogic.all) {\n      for (var d in discovered) {\n        if (d.wonder == w.type) return d;\n      }\n    }\n    return null;\n  }\n\n  bool isLost(WonderType wonderType, int i) {\n    final datas = forWonder(wonderType);\n    final states = statesById.value;\n    if (datas.length > i && states.containsKey(datas[i].id)) {\n      return states[datas[i].id] == CollectibleState.lost;\n    }\n    return true;\n  }\n\n  void reset() {\n    Map<String, int> states = {};\n    for (int i = 0; i < all.length; i++) {\n      states[all[i].id] = CollectibleState.lost;\n    }\n    _updateNativeHomeWidgetData(); // clear home widget data\n    statesById.value = states;\n    debugPrint('collection reset');\n    scheduleSave();\n  }\n\n  Future<void> _updateNativeHomeWidgetData({\n    String title = '',\n    String id = '',\n    String imageUrl = '',\n  }) async {\n    if (!_nativeWidget.isSupported) return;\n    // Save title\n    await _nativeWidget.save<String>('lastDiscoveredTitle', title);\n    // Subtitle\n    String subTitle = '';\n    if (id.isNotEmpty) {\n      final artifactData = await artifactLogic.getArtifactByID(id);\n      subTitle = artifactData?.date ?? '';\n    }\n    await _nativeWidget.save<String>('lastDiscoveredSubTitle', subTitle);\n    // Image,\n    // Download, convert to base64 string and write to shared widget data\n    String imageBase64 = '';\n    if (imageUrl.isNotEmpty) {\n      var bytes = await http.readBytes(Uri.parse(imageUrl));\n      imageBase64 = base64Encode(bytes);\n      debugPrint('Saving base64 bytes for homeWidget');\n    }\n    await _nativeWidget.save<String>('lastDiscoveredImageData', imageBase64);\n    await _nativeWidget.markDirty();\n  }\n\n  @override\n  void copyFromJson(Map<String, dynamic> value) {\n    Map<String, int> states = {};\n    for (int i = 0; i < all.length; i++) {\n      String id = all[i].id;\n      states[id] = value[id] ?? CollectibleState.lost;\n    }\n    statesById.value = states;\n  }\n\n  @override\n  Map<String, dynamic> toJson() => statesById.value;\n}","file":"lib/logic/collectibles_logic.dart","kind":"class","line":9,"members":{"_discoveredCount":[19,19],"_exploredCount":[23,23],"_nativeWidget":[27,27],"_updateCounts":[52,64],"_updateNativeHomeWidgetData":[100,125],"all":[13,14],"copyFromJson":[127,135],"discoveredCount":[21,21],"exploredCount":[25,25],"fileName":[10,11],"forWonder":[33,35],"fromId":[31,31],"getFirstDiscoveredOrNull":[66,78],"init":[29,29],"isLost":[80,87],"reset":[89,98],"setState":[37,50],"statesById":[16,17],"toJson":[137,138]},"supers":["ThrottledSaveLoadMixin"]},"CollectionScreen":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"class CollectionScreen extends StatefulWidget with GetItStatefulWidgetMixin {\n  CollectionScreen({required this.fromId, super.key});\n\n  final String fromId;\n\n  @override\n  State<CollectionScreen> createState() => _CollectionScreenState();\n}","file":"lib/ui/screens/collection/collection_screen.dart","kind":"class","line":21,"members":{"CollectionScreen":[22,22],"createState":[26,27],"fromId":[24,24]},"shot":"shots/code/CollectionScreen.jpg","supers":["StatefulWidget","GetItStatefulWidgetMixin","_CollectionScreenState"]},"HiddenCollectible":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["editorial","h-widgets","Screen \u00b7 widget composition"],["events","h-widgets","Screen \u00b7 widget composition"],["photo-gallery","h-widgets","Screen \u00b7 widget composition"]],"code":"/// Shows a [CollectibleItem], for a specific set of wonders.\n/// The item is looked up via index, and expects that 3 items always exist for each wonder.\n/// If `wonders` is empty, then the collectible is always shown.\nclass HiddenCollectible extends StatelessWidget with GetItMixin {\n  HiddenCollectible(\n    this.currentWonder, {\n    super.key,\n    required this.index,\n    this.matches = const [],\n    this.size = 64,\n    this.focus,\n  }) : assert(index <= 2, 'index should not exceed 2');\n  final int index;\n  final double size;\n  final List<WonderType> matches;\n  final WonderType currentWonder;\n  final FocusNode? focus;\n  @override\n  Widget build(BuildContext context) {\n    final data = collectiblesLogic.forWonder(currentWonder);\n    assert(data.length == 3, 'Each wonder should have exactly 3 collectibles');\n    if (matches.isNotEmpty && matches.contains(currentWonder) == false) {\n      return SizedBox.shrink();\n    }\n    return CollectibleItem(data[index], size: size, focus: focus);\n  }\n}","file":"lib/ui/common/hidden_collectible.dart","kind":"class","line":4,"members":{"HiddenCollectible":[8,15],"build":[21,29],"currentWonder":[19,19],"focus":[20,20],"index":[16,16],"matches":[18,18],"size":[17,17]},"shot":"shots/code/HiddenCollectible.jpg","supers":["StatelessWidget","GetItMixin"]},"NativeWidgetService":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens talk through"]],"code":"/// Small facade for the HomeWidget package\nclass NativeWidgetService {\n  static const _iosAppGroupId = 'group.com.gskinner.flutter.wonders.widget';\n  static const _iosAppName = 'WonderousWidget';\n\n  final bool isSupported = PlatformInfo.isIOS;\n\n  Future<void> init() async {\n    if (!isSupported) return;\n    await HomeWidget.setAppGroupId(_iosAppGroupId);\n  }\n\n  Future<bool?> save<T>(String s, T value, {void Function(bool?)? onSaveComplete}) async {\n    if (!isSupported) return false;\n    return await HomeWidget.saveWidgetData<T>(s, value).then((value) {\n      onSaveComplete?.call(value);\n      return null;\n    });\n  }\n\n  Future<bool?> markDirty() async {\n    if (!isSupported) return false;\n    return await HomeWidget.updateWidget(iOSName: _iosAppName);\n  }\n}","file":"lib/logic/native_widget_service.dart","kind":"class","line":4,"members":{"_iosAppGroupId":[6,6],"_iosAppName":[7,7],"init":[11,14],"isSupported":[9,9],"markDirty":[24,27],"save":[16,22]},"supers":[]},"ThrottledSaveLoadMixin":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["splash","h-classes","Logic \u00b7 class diagram"]],"code":"mixin ThrottledSaveLoadMixin {\n  late final _file = JsonPrefsFile(fileName);\n  final _throttle = Throttler(const Duration(seconds: 2));\n\n  Future<void> load() async {\n    final results = await _file.load();\n    try {\n      copyFromJson(results);\n    } on Exception catch (e) {\n      debugPrint(e.toString());\n    }\n  }\n\n  Future<void> save() async {\n    if (!kIsWeb) debugPrint('Saving...');\n    try {\n      await _file.save(toJson());\n    } on Exception catch (e) {\n      debugPrint(e.toString());\n    }\n  }\n\n  Future<void> scheduleSave() async => _throttle.call(save);\n\n  /// Serialization\n  String get fileName;\n  Map<String, dynamic> toJson();\n  void copyFromJson(Map<String, dynamic> value);\n}","file":"lib/logic/common/save_load_mixin.dart","kind":"mixin","line":5,"members":{"_file":[6,6],"_throttle":[7,7],"copyFromJson":[32,32],"fileName":[29,30],"load":[9,16],"save":[18,25],"scheduleSave":[27,27],"toJson":[31,31]},"supers":[]},"_AnimatedRibbon":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"class _AnimatedRibbon extends StatelessWidget {\n  const _AnimatedRibbon(this.text);\n\n  final String text;\n  static const double height = 48;\n\n  @override\n  Widget build(BuildContext context) {\n    return Stack(\n      children: [\n        Positioned.fill(\n          child: Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              _buildEnd(context, false),\n              Spacer(),\n              _buildEnd(context, true),\n            ],\n          ),\n        ),\n        Container(\n          height: height,\n          color: $styles.colors.accent1,\n          padding: EdgeInsets.symmetric(horizontal: $styles.insets.sm),\n          margin: EdgeInsets.only(bottom: 10),\n          // this aligns the text vertically, without expanding the container:\n          child: Column(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [Text(text, textAlign: TextAlign.center, style: $styles.text.title1)],\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildEnd(BuildContext context, bool flip) {\n    Widget end = Image.asset(ImagePaths.ribbonEnd, height: height);\n    if (flip) end = Transform.scale(scaleX: -1, child: end);\n    double m = flip ? 1 : -1;\n    return end.maybeAnimate().move(\n      begin: Offset(m * 8, 2),\n      end: Offset(m * 32, 10),\n      duration: 400.animateMs,\n      curve: Curves.easeOut,\n    );\n  }\n}","file":"lib/ui/screens/collectible_found/widgets/_animated_ribbon.dart","kind":"class","line":3,"members":{"_AnimatedRibbon":[4,4],"_buildEnd":[38,48],"build":[9,36],"height":[7,7],"text":[6,6]},"supers":["StatelessWidget"]},"_CelebrationParticles":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"class _CelebrationParticles extends StatelessWidget {\n  const _CelebrationParticles({this.fadeMs = 1000});\n\n  final int fadeMs;\n\n  @override\n  Widget build(BuildContext context) {\n    final Color color = $styles.colors.accent1;\n    int particleCount = 1200;\n\n    return Positioned.fill(\n      child: RepaintBoundary(\n        child: ParticleField(\n          blendMode: BlendMode.dstIn,\n          spriteSheet: SpriteSheet(\n            image: AssetImage(ImagePaths.particle),\n            frameWidth: 21,\n            scale: 0.75,\n          ),\n          onTick: (controller, elapsed, size) {\n            List<Particle> particles = controller.particles;\n\n            // calculate base distance from center & velocity based on width/height:\n            final double d = min(size.width, size.height) * 0.3;\n            final double v = d * 0.08;\n\n            // calculate an opacity multiplier based on time elapsed (ie. fade out):\n            controller.opacity = Curves.easeOutExpo.transform(\n              max(0, 1 - elapsed.inMilliseconds / fadeMs),\n            );\n            if (controller.opacity == 0) return;\n\n            // add new particles, reducing the number added each tick:\n            int addCount = particleCount ~/ 30;\n            particleCount -= addCount;\n            while (--addCount > 0) {\n              final double angle = rnd.getRad();\n              particles.add(\n                Particle(\n                  // adding random variation makes it more visually interesting:\n                  x: cos(angle) * d * rnd(0.8, 1),\n                  y: sin(angle) * d * rnd(0.8, 1),\n                  vx: cos(angle) * v * rnd(0.5, 1.5),\n                  vy: sin(angle) * v * rnd(0.5, 1.5),\n                  color: color.withValues(alpha: rnd(0.5, 1)),\n                ),\n              );\n            }\n\n            // update existing particles & remove old ones:\n            for (int i = particles.length - 1; i >= 0; i--) {\n              final Particle o = particles[i];\n              o.update(frame: o.age ~/ 3);\n              if (o.age > 40) particles.removeAt(i);\n            }\n          },\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/collectible_found/widgets/_celebration_particles.dart","kind":"class","line":3,"members":{"_CelebrationParticles":[4,4],"build":[8,62],"fadeMs":[6,6]},"supers":["StatelessWidget"]},"_CollectibleImage":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"class _CollectibleImage extends StatelessWidget {\n  const _CollectibleImage({\n    required this.collectible,\n    required this.state,\n    required this.onPressed,\n    this.heroTag,\n  });\n\n  final CollectibleData collectible;\n  final ValueSetter<CollectibleData> onPressed;\n  final int state;\n  final String? heroTag;\n\n  @override\n  Widget build(BuildContext context) {\n    return RepaintBoundary(\n      child: state == CollectibleState.lost\n          ? _buildHidden(context, collectible)\n          : _buildFound(context, collectible, state),\n    );\n  }\n\n  Widget _buildHidden(BuildContext context, CollectibleData collectible) {\n    return Container(\n      color: $styles.colors.black,\n      child: Center(\n        child: FractionallySizedBox(\n          widthFactor: 0.66,\n          heightFactor: 0.66,\n          child: Image(\n            image: collectible.icon,\n            color: $styles.colors.black,\n            colorBlendMode: BlendMode.color,\n            opacity: AlwaysStoppedAnimation(0.2),\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildFound(BuildContext context, CollectibleData collectible, int state) {\n    final bool isNew = state == CollectibleState.discovered;\n    Widget content = Container(\n      width: double.infinity,\n      height: double.infinity,\n      decoration: BoxDecoration(\n        color: $styles.colors.black,\n        border: isNew ? Border.all(color: $styles.colors.accent1, width: 3) : null,\n        boxShadow: !isNew\n            ? null\n            : [\n                BoxShadow(\n                  color: $styles.colors.accent1.withValues(alpha: 0.6),\n                  blurRadius: $styles.insets.sm,\n                ),\n              ],\n      ),\n      child: AppImage(\n        image: NetworkImage(collectible.imageUrlSmall),\n        fit: BoxFit.cover,\n        scale: 0.5,\n      ),\n    );\n\n    return AppBtn.basic(\n      semanticLabel: collectible.title,\n      onPressed: () => onPressed(collectible),\n      child: content,\n    );\n  }\n}","file":"lib/ui/screens/collection/widgets/_collectible_image.dart","kind":"class","line":3,"members":{"_CollectibleImage":[4,9],"_buildFound":[43,72],"_buildHidden":[25,41],"build":[16,23],"collectible":[11,11],"heroTag":[14,14],"onPressed":[12,12],"state":[13,13]},"supers":["StatelessWidget"]},"_CollectionFooter":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"@immutable\nclass _CollectionFooter extends StatelessWidget {\n  const _CollectionFooter({required this.count, required this.total});\n\n  final int count;\n  final int total;\n\n  @override\n  Widget build(BuildContext context) {\n    return Stack(\n      children: [\n        // TODO SB: Maybe restore this gradient? Need to come up with alternate approach since list can now scroll horizontally\n        // Transform.translate(\n        //   offset: Offset(0, -$styles.insets.xl),\n        //   child: VtGradient(\n        //     [$styles.colors.greyStrong.withValues(alpha:0), $styles.colors.greyStrong],\n        //     const [0, 1],\n        //     height: $styles.insets.xl,\n        //   ),\n        // ),\n        Container(\n          padding: EdgeInsets.symmetric(horizontal: $styles.insets.md, vertical: $styles.insets.sm),\n          color: $styles.colors.greyStrong,\n          child: SafeArea(\n            top: false,\n            child: CenteredBox(\n              width: $styles.sizes.maxContentWidth1,\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  _buildProgressRow(context),\n                  Gap($styles.insets.sm),\n                  _buildProgressBar(context),\n                  Gap($styles.insets.sm),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildProgressRow(BuildContext context) {\n    int percent = (count / total * 100).round();\n    return Row(\n      children: [\n        Text(\n          $strings.collectionLabelDiscovered(percent),\n          style: $styles.text.body.copyWith(color: $styles.colors.accent1),\n        ),\n        Spacer(),\n        Text(\n          $strings.collectionLabelCount(count, total),\n          style: $styles.text.body.copyWith(color: $styles.colors.offWhite),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildProgressBar(BuildContext context) {\n    return RepaintBoundary(\n      child: Container(\n        height: $styles.insets.xs,\n        decoration: BoxDecoration(\n          color: $styles.colors.white.withValues(alpha: 0.25),\n          borderRadius: BorderRadius.circular(1000),\n        ),\n        child:\n            Container(\n                  decoration: BoxDecoration(\n                    color: $styles.colors.accent1,\n                    borderRadius: BorderRadius.circular(1000),\n                  ),\n                )\n                .maybeAnimate()\n                .fade(duration: 1500.animateMs, curve: Curves.easeOutExpo)\n                .custom(\n                  builder: (_, m, child) => FractionallySizedBox(\n                    alignment: Alignment.centerLeft,\n                    widthFactor: m * count / total,\n                    child: child,\n                  ),\n                ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/collection/widgets/_collection_footer.dart","kind":"class","line":3,"members":{"_CollectionFooter":[5,5],"_buildProgressBar":[63,89],"_buildProgressRow":[46,61],"build":[10,44],"count":[7,7],"total":[8,8]},"shot":"shots/code/_CollectionFooter.jpg","supers":["StatelessWidget"]},"_CollectionList":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"@immutable\nclass _CollectionList extends StatefulWidget with GetItStatefulWidgetMixin {\n  _CollectionList({\n    this.onReset,\n    required this.fromId,\n    this.scrollKey,\n  });\n\n  static const double _vtCardExtent = 300;\n  static const double _hzCardExtent = 600;\n  final VoidCallback? onReset;\n  final Key? scrollKey;\n  final String fromId;\n\n  @override\n  State<_CollectionList> createState() => _CollectionListState();\n}","file":"lib/ui/screens/collection/widgets/_collection_list.dart","kind":"class","line":3,"members":{"_CollectionList":[5,9],"_hzCardExtent":[12,12],"_vtCardExtent":[11,11],"createState":[17,18],"fromId":[15,15],"onReset":[13,13],"scrollKey":[14,14]},"shot":"shots/code/_CollectionList.jpg","supers":["StatefulWidget","GetItStatefulWidgetMixin","_CollectionListState"]},"_CollectionListCard":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-widgets","Screen \u00b7 widget composition"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"]],"code":"class _CollectionListCard extends StatelessWidget with GetItMixin {\n  _CollectionListCard({\n    super.key,\n    this.width,\n    this.height,\n    required this.data,\n    required this.fromId,\n  });\n\n  final double? width;\n  final double? height;\n  final WonderData data;\n  final String fromId;\n\n  void _showDetails(BuildContext context, CollectibleData collectible) {\n    context.go(ScreenPaths.artifact(collectible.artifactId));\n    Future.delayed(\n      300.delayMs,\n    ).then((_) => collectiblesLogic.setState(collectible.id, CollectibleState.explored));\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final states = watchX((CollectiblesLogic o) => o.statesById);\n    List<CollectibleData> collectibles = collectiblesLogic.forWonder(data.type);\n    return Center(\n      child: SizedBox(\n        width: width ?? double.infinity,\n        height: height ?? double.infinity,\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            /// Title\n            Text(\n              data.title.toUpperCase(),\n              textAlign: TextAlign.left,\n              style: $styles.text.title1.copyWith(color: $styles.colors.offWhite),\n            ),\n            Gap($styles.insets.md),\n\n            /// Images\n            Expanded(\n              child: SeparatedRow(\n                separatorBuilder: () => Gap($styles.insets.sm),\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  ...collectibles.map((e) {\n                    int state = states[e.id] ?? CollectibleState.lost;\n                    return Flexible(\n                      child: _CollectibleImage(\n                        collectible: e,\n                        state: state,\n                        onPressed: (c) => _showDetails(context, c),\n                        heroTag: e.id == fromId ? 'collectible_image_$fromId' : null,\n                      ),\n                    );\n                  }),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/collection/widgets/_collection_list_card.dart","kind":"class","line":3,"members":{"_CollectionListCard":[4,10],"_showDetails":[17,22],"build":[24,67],"data":[14,14],"fromId":[15,15],"height":[13,13],"width":[12,12]},"shot":"shots/code/_CollectionListCard.jpg","supers":["StatelessWidget","GetItMixin"]},"_CollectionListState":{"code":"class _CollectionListState extends State<_CollectionList> with GetItStateMixin {\n  final ScrollController scrollController = ScrollController();\n\n  late final ValueNotifier<bool> _vtMode = ValueNotifier(true)..addListener(_maintainScrollPos);\n\n  WonderType? get scrollTargetWonder {\n    CollectibleData? item;\n    if (widget.fromId.isEmpty) {\n      item = collectiblesLogic.getFirstDiscoveredOrNull();\n    } else {\n      item = collectiblesLogic.fromId(widget.fromId);\n    }\n    return item?.wonder;\n  }\n\n  // Maintain scroll position when switching between vertical and horizontal orientation.\n  // Multiplies or divides the current scroll position by the ratio of the vertical and horizontal card extents.\n  void _maintainScrollPos() {\n    if (scrollController.hasClients == false) return;\n    const extentFactor = _CollectionList._vtCardExtent / _CollectionList._hzCardExtent;\n    final currentPx = scrollController.position.pixels;\n    if (_vtMode.value == true) {\n      scrollController.jumpTo(currentPx * extentFactor);\n    } else {\n      scrollController.jumpTo(currentPx / extentFactor);\n    }\n  }\n\n  void _handleMouseWheel(PointerSignalEvent event) {\n    if (event is PointerScrollEvent && event.kind == PointerDeviceKind.mouse && _vtMode.value == false) {\n      final offset = event.scrollDelta.dy;\n      scrollController.jumpTo(scrollController.offset + offset);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    watchX((CollectiblesLogic o) => o.statesById);\n    List<WonderData> wonders = wondersLogic.all;\n    _vtMode.value = context.isLandscape == false;\n    final scrollWonder = scrollTargetWonder;\n    // Create list of collections that is shared by both hz and vt layouts\n    List<Widget> collections = [\n      ...wonders.map((d) {\n        return _CollectionListCard(\n          key: d.type == scrollWonder ? widget.scrollKey : null,\n          width: _vtMode.value ? null : _CollectionList._hzCardExtent,\n          height: _vtMode.value ? _CollectionList._vtCardExtent : 400,\n          fromId: widget.fromId,\n          data: d,\n        );\n      }),\n    ];\n    // Scroll view adapts to scroll vertically or horizontally\n    return Listener(\n      onPointerSignal: _handleMouseWheel,\n      child: SingleChildScrollView(\n        controller: scrollController,\n        scrollDirection: _vtMode.value ? Axis.vertical : Axis.horizontal,\n        child: Padding(\n          padding: EdgeInsets.all($styles.insets.lg),\n          child: SeparatedFlex(\n            direction: _vtMode.value ? Axis.vertical : Axis.horizontal,\n            mainAxisSize: MainAxisSize.min,\n            separatorBuilder: () => Gap($styles.insets.lg),\n            children: [\n              ...collections,\n              Gap($styles.insets.sm),\n              if (kDebugMode) _buildResetBtn(context),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildResetBtn(BuildContext context) {\n    Widget btn = AppBtn.from(\n      onPressed: widget.onReset ?? () {},\n      text: $strings.collectionButtonReset,\n      isSecondary: true,\n      expand: true,\n    );\n    return AnimatedOpacity(\n      opacity: widget.onReset == null ? 0.25 : 1,\n      duration: $styles.times.fast,\n      child: btn,\n    );\n  }\n}","file":"lib/ui/screens/collection/widgets/_collection_list.dart","kind":"class","line":21,"members":{"_buildResetBtn":[97,109],"_handleMouseWheel":[49,54],"_maintainScrollPos":[38,47],"_vtMode":[24,24],"build":[56,95],"scrollController":[22,22],"scrollTargetWonder":[26,34]},"supers":["State","GetItStateMixin"]},"_CollectionScreenState":{"appearsIn":[["collection","h-classes","Logic \u00b7 class diagram"],["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"]],"code":"class _CollectionScreenState extends State<CollectionScreen> with GetItStateMixin {\n  final GlobalKey _scrollKey = GlobalKey();\n\n  @override\n  void initState() {\n    super.initState();\n    final states = collectiblesLogic.statesById.value;\n    if (widget.fromId.isNotEmpty && states[widget.fromId] == CollectibleState.discovered) {\n      scheduleMicrotask(() => _scrollToTarget(false));\n    }\n  }\n\n  void _scrollToTarget([bool animate = true]) {\n    if (_scrollKey.currentContext != null) {\n      Scrollable.ensureVisible(\n        _scrollKey.currentContext!,\n        alignment: 0.15,\n        duration: (animate ? 300 : 0).animateMs,\n      );\n    }\n  }\n\n  void _handleReset() async {\n    String msg = $strings.collectionPopupResetConfirm;\n    final result = await showModal(context, child: OkCancelModal(msg: msg));\n    if (result == true) {\n      collectiblesLogic.reset();\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // Rebuild when collectible states change\n    watchX((CollectiblesLogic o) => o.statesById);\n    int discovered = collectiblesLogic.discoveredCount;\n    int explored = collectiblesLogic.exploredCount;\n    int total = collectiblesLogic.all.length;\n\n    return ColoredBox(\n      color: $styles.colors.greyStrong,\n      child: Column(\n        children: [\n          Expanded(\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                AppHeader(title: $strings.collectionTitleCollection, isTransparent: true),\n                _NewlyDiscoveredItemsBtn(count: discovered, onPressed: _scrollToTarget),\n                Flexible(\n                  child: _CollectionList(\n                    fromId: widget.fromId,\n                    scrollKey: _scrollKey,\n                    onReset: discovered + explored > 0 ? _handleReset : null,\n                  ),\n                ),\n              ],\n            ),\n          ),\n          _CollectionFooter(count: discovered + explored, total: total),\n        ],\n      ),\n    );\n  }\n}","file":"lib/ui/screens/collection/collection_screen.dart","kind":"class","line":30,"members":{"_handleReset":[52,58],"_scrollKey":[31,31],"_scrollToTarget":[42,50],"build":[60,92],"initState":[33,40]},"supers":["State","GetItStateMixin"]},"_NewlyDiscoveredItemsBtn":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"]],"code":"@immutable\nclass _NewlyDiscoveredItemsBtn extends StatelessWidget {\n  const _NewlyDiscoveredItemsBtn({this.count = 0, required this.onPressed});\n\n  final int count;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    if (count == 0) return SizedBox.shrink();\n\n    return AppBtn.basic(\n      semanticLabel: $strings.newlyDiscoveredSemanticNew(count, count == 1 ? '' : 's'),\n      onPressed: onPressed,\n      child: Container(\n        alignment: Alignment.center,\n        height: 40,\n        color: $styles.colors.black,\n        padding: EdgeInsets.symmetric(vertical: $styles.insets.xs),\n        child: Text(\n          $strings.newlyDiscoveredLabelNew(count, count == 1 ? '' : 's'),\n          textAlign: TextAlign.center,\n          textHeightBehavior: TextHeightBehavior(applyHeightToFirstAscent: false),\n          style: $styles.text.bodySmallBold.copyWith(color: $styles.colors.accent1),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/collection/widgets/_newly_discovered_items_btn.dart","kind":"class","line":3,"members":{"_NewlyDiscoveredItemsBtn":[5,5],"build":[10,30],"count":[7,7],"onPressed":[8,8]},"supers":["StatelessWidget"]}},"sourceUrl":"https://github.com/gskinnerTeam/flutter-wonderous-app/blob/30ccc36a276223ebbb85dbb290d6ff2facf001ed/"};
